        st.open=false;st.epoch++;st.stop=true;st.controller?.abort();clearTimeout(st.timer);cclSave();st.host?.remove();st.host=null;st.sh=null;st.selected.clear();if(st.back?.isConnected)st.back.focus({preventScroll:true});
