                return;
            const input = event.target?.closest?.('textarea[placeholder*="메시지"], textarea[aria-label*="메시지"], [contenteditable="true"]');
            if (input && isChatInputElement(input))
                cacRememberGenerationStart({ is_regenerate: false });
